import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';

const VideoProcessor = ({ colorblindType, mode }) => {
  const [file, setFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const fileInputRef = useRef(null);
  const progressTimerRef = useRef(null);

  const handleFileSelect = (e) => {
    const selected = e.target.files[0];
    if (!selected || !selected.type.startsWith('video/')) {
      setError('Please select a valid video file');
      return;
    }
    setFile(selected);
    setError(null);
    setResult(null);
  };

  const startFakeProgress = () => {
    setProgress(0);
    progressTimerRef.current = setInterval(() => {
      setProgress(prev => {
        if (prev >= 95) return prev;
        return prev + Math.random() * 4;
      });
    }, 400);
  };

  const stopFakeProgress = () => {
    clearInterval(progressTimerRef.current);
    setProgress(100);
  };

  const processVideo = async () => {
    if (!file) {
      setError('Please select a video file');
      return;
    }

    try {
      setProcessing(true);
      setError(null);
      setResult(null);
      startFakeProgress();

      const formData = new FormData();
      formData.append('video', file);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const res = await axios.post(
        'http://localhost:5000/api/process-video',
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      stopFakeProgress();

      if (res.data.success) {
        setResult({
          outputFile: res.data.output_file,
          frames: res.data.frames_processed,
        });
      } else {
        setError(res.data.error || 'Processing failed');
      }
    } catch (err) {
      setError('Error processing video: ' + err.message);
    } finally {
      setProcessing(false);
    }
  };

  const downloadVideo = () => {
    const link = document.createElement('a');
    link.href = `http://localhost:5000/api/download/${result.outputFile}`;
    link.download = result.outputFile;
    link.click();
  };

  return (
    <div className="component-container">
      <h2>Video Processor</h2>

      {error && <div className="error">{error}</div>}

      <div
        className="upload-area"
        onClick={() => fileInputRef.current?.click()}
        style={{
          padding: '40px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          textAlign: 'center',
          cursor: 'pointer',
        }}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="video/*"
          onChange={handleFileSelect}
          hidden
        />
        {!file ? 'Click to upload video' : `✓ ${file.name}`}
      </div>

      <div style={{ marginTop: '20px', textAlign: 'center' }}>
        <button
          onClick={processVideo}
          disabled={!file || processing}
          style={{
            padding: '10px 20px',
            background: '#5d35c4',
            color: '#fff',
            borderRadius: '8px',
            border: 'none',
            cursor: processing ? 'not-allowed' : 'pointer',
          }}
        >
          {processing ? 'Processing…' : 'Process Video'}
        </button>
      </div>

      {/* PROGRESS BAR */}
      {processing && (
        <div style={{ marginTop: '25px', textAlign: 'center' }}>
          <p>Processing video… {Math.floor(progress)}%</p>
          <div
            style={{
              width: '80%',
              height: '10px',
              background: '#ddd',
              margin: 'auto',
              borderRadius: '5px',
            }}
          >
            <div
              style={{
                height: '100%',
                width: `${progress}%`,
                background: '#5d35c4',
                transition: 'width 0.4s',
                borderRadius: '5px',
              }}
            />
          </div>
        </div>
      )}

      {/* RESULT */}
      {result && !processing && (
        <div style={{ marginTop: '20px', textAlign: 'center' }}>
          <p style={{ color: 'green' }}>
            ✓ Video processed ({result.frames} frames)
          </p>
          <button
            onClick={downloadVideo}
            style={{
              padding: '10px 20px',
              background: '#4caf50',
              color: '#fff',
              borderRadius: '8px',
              border: 'none',
              cursor: 'pointer',
            }}
          >
            Download Video
          </button>
        </div>
      )}
    </div>
  );
};

export default VideoProcessor;
